contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 x, uint64 n) public payable {
        require(true);
        string memory v = c.version();
        assert(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 n, uint256 x) public payable {
        require(true);
        bool reverted;
        try c.setL1BlockValues(n, n, x, bytes32(x), n, bytes32(x), x, x) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint64 num = c.number();
        assert(num == 0 && reverted);
    }
    receive() external payable {}
}

