contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint64 n, uint256 x, uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.setL1BlockValues{value: amount}(n, n, x, bytes32(uint256(1)), n, bytes32(uint256(1)), x, x) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && address(c).balance == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(
            reverted
            && keccak256(bytes(c.version())) == keccak256(bytes("1.0.0"))
            && c.number() == 0
            && c.timestamp() == 0
            && c.basefee() == 0
            && c.hash() == bytes32(0)
            && c.sequenceNumber() == 0
            && c.batcherHash() == bytes32(0)
            && c.l1FeeOverhead() == 0
            && c.l1FeeScalar() == 0
        );
    }
    receive() external payable {}
}
